"""Project-level compilation: files on disk in, HTML files out."""

from __future__ import annotations

import shutil
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional

from .emitter import Emitter
from .errors import HtvlError
from .parser import parse
from .templates import load_templates

CGI_SHEBANG = "#!/usr/bin/env bash"
CGI_TEMPLATE = """{shebang}
# Generated by htvl from {source} - a self-contained CGI script.
cat <<'HTVL_DOCUMENT'
{html}HTVL_DOCUMENT
"""


@dataclass
class CompileResult:
    """What a compilation run produced."""

    outputs: List[Path] = field(default_factory=list)
    copied_assets: Optional[Path] = None
    source: Optional[Path] = None


def compile_source(
    source: str,
    templates: Optional[Dict[str, str]] = None,
) -> str:
    """Compile HTVL source text to HTML.

    ``templates`` maps template names (``$headtags``, ``nav0``, ...) to their
    HTVL source text.
    """
    document = parse(source)
    return Emitter(templates=templates).emit(document)


def compile_file(
    src: Path,
    out: Path,
    templates: Optional[Dict[str, str]] = None,
) -> Path:
    """Compile one ``.htvl`` file to ``out``."""
    html = compile_source(Path(src).read_text(encoding="utf-8"), templates)
    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(html, encoding="utf-8")
    return out


def _write_cgi(src: Path, out: Path, html: str) -> Path:
    out = Path(out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        CGI_TEMPLATE.format(shebang=CGI_SHEBANG, source=src.name, html=html),
        encoding="utf-8",
    )
    out.chmod(0o755)
    return out


def find_sources(root: Path) -> List[Path]:
    """Every ``.htvl`` / ``.cal`` file directly inside ``root``."""
    root = Path(root)
    sources: List[Path] = []
    for pattern in ("*.htvl", "*.cal"):
        sources.extend(sorted(root.glob(pattern)))
    return sources


def compile_project(
    root: Path,
    out_dir: str = "public",
    force: bool = False,
) -> CompileResult:
    """Compile every HTVL/CAL file in ``root``.

    ``*.htvl`` files produce ``<out_dir>/<name>.html``; ``*.cal`` files produce
    ``cal/<name>``, a self-contained executable CGI script. ``assets/`` is
    copied into the output directory when present.
    """
    root = Path(root)
    out_path = root / out_dir
    result = CompileResult(source=root)

    templates = load_templates(root / "templates")
    sources = find_sources(root)
    if not sources:
        raise HtvlError(
            f"no .htvl or .cal files found in '{root}'. "
            "Run 'htvl new mysite' to scaffold a project."
        )

    for src in sources:
        html = compile_source(src.read_text(encoding="utf-8"), templates)
        if src.suffix == ".cal":
            target = root / "cal" / src.stem
            result.outputs.append(_write_cgi(src, target, html))
        else:
            target = out_path / (src.stem + ".html")
            result.outputs.append(compile_file(src, target, templates))

    assets = root / "assets"
    if assets.is_dir():
        destination = out_path / "assets"
        if destination.exists():
            shutil.rmtree(destination)
        shutil.copytree(assets, destination)
        result.copied_assets = destination

    return result
